mapper.sql:
s.id, s.store_code, s.store_name, s.address, s.phone, s.business_hours, s.longitude, s.latitude, s.manager_id, (SELECT m.real_name FROM sys_user m WHERE m.id = s.manager_id AND m.deleted = 0) AS manager_name, s.status, s.create_time,
/* ---------- 车辆资产 ---------- */ (SELECT COUNT(*) FROM vehicle v WHERE v.store_id = s.id AND v.deleted = 0) AS vehicle_total, (SELECT COUNT(*) FROM vehicle v WHERE v.store_id = s.id AND v.deleted = 0 AND v.status = 1) AS vehicle_available, (SELECT COUNT(*) FROM vehicle v WHERE v.store_id = s.id AND v.deleted = 0 AND v.status = 2) AS vehicle_rented, (SELECT COUNT(*) FROM vehicle v WHERE v.store_id = s.id AND v.deleted = 0 AND v.status = 3) AS vehicle_maintenance,
/* ---------- 经营 ---------- */ (SELECT COUNT(*) FROM lease_order o WHERE o.store_id = s.id AND o.deleted = 0 AND o.status <> 'CANCELLED') AS order_total, (SELECT COUNT(*) FROM lease_order o WHERE o.store_id = s.id AND o.deleted = 0 AND o.status IN ('WAIT_PICKUP', 'IN_USE', 'WAIT_RETURN', 'OVERDUE')) AS active_order_count, (SELECT COALESCE(SUM(o.total_amount), 0) FROM lease_order o WHERE o.store_id = s.id AND o.deleted = 0 AND o.status NOT IN ('CANCELLED', 'WAIT_PAY') AND o.create_time >= DATE_FORMAT(CURDATE(), '%Y-%m-01')) AS month_revenue

mapper.select:
SELECT

FROM store s
WHERE s.deleted = 0 AND s.id = #{id}

SELECT COUNT(*) FROM store
 WHERE store_code = #{storeCode}

    AND id <> #{excludeId}
